    def _instrument_files(self, source: Path) -> list[tuple[str, Path]]:
        checkout = source.parent
        files: list[tuple[str, Path]] = []
        for prefix in self.INSTRUMENT_PREFIXES:
            folder = checkout / prefix
            if not folder.is_dir():
                continue
            for path in sorted(folder.rglob("*")):
                if not path.is_file() or "__pycache__" in path.parts or path.name.endswith(".tmp"):
                    continue
                resolved = path.resolve()
                if checkout.resolve() not in resolved.parents:
                    raise CommandError(f"Instrument source symlink escapes checkout: {path}")
                files.append((path.relative_to(checkout).as_posix(), path))
        return files

    def instrument_tree_hash(self, source: Path) -> tuple[str, list[dict]]:
        digest = hashlib.sha256()
        entries: list[dict] = []
        for relative, path in self._instrument_files(source):
            file_hash = Registry._file_digest(path)
            digest.update(relative.encode("utf-8") + b"\0" + file_hash.encode("ascii") + b"\n")
            entries.append({"path": relative, "sha256": file_hash, "size": path.stat().st_size})
        if not entries:
            raise CommandError(f"No deployed instrument files found under {source}")
        return digest.hexdigest(), entries

    def _snapshot(self, runtime_id: str, deployment_id: str, task_id: str,
                  worktree: Path, source: Path, branch: str, head: str,
                  dirty: bool, build: str) -> dict:
        folder = self.store.runtime / "live" / runtime_id / "deployments" / deployment_id
        if folder.exists() or folder.is_symlink():
            raise CommandError(f"Deployment evidence already exists: {folder}")
        source_folder = folder / "source"
        source_folder.mkdir(parents=True)
        tree_hash, entries = self.instrument_tree_hash(source)
        for entry in entries:
            source_file = worktree / entry["path"]
            destination = source_folder / entry["path"]
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source_file, destination)
        patch = self._git_text(worktree, "diff", "--binary", "HEAD")
        (folder / "dirty.patch").write_text(patch, encoding="utf-8", newline="\n")
        untracked = self._git_text(
            worktree, "ls-files", "--others", "--exclude-standard", "-z"
        ).split("\0")
        copied_untracked: list[dict] = []
        for relative in sorted(item for item in untracked if item):
            if not relative.startswith(self.INSTRUMENT_PREFIXES):
                continue
            source_file = worktree / relative
            if not source_file.is_file():
                continue
            destination = folder / "untracked" / relative
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source_file, destination)
            copied_untracked.append({"path": relative, "sha256": Registry._file_digest(destination)})
        patch_hash = Registry._file_digest(folder / "dirty.patch")
        snapshot_hash = hashlib.sha256(
            f"tree:{tree_hash}\npatch:{patch_hash}\n".encode("ascii")
        ).hexdigest()
        manifest = {
            "schemaVersion": 1,
            "deploymentId": deployment_id,
            "runtime": runtime_id,
            "taskId": task_id,
            "sourceRepo": "fgcnote-sf6-mod",
            "sourceWorktree": str(worktree),
            "sourceReframework": str(source),
            "branch": branch,
            "headRevision": head,
            "instrumentDirty": dirty,
            "instrumentTreeHash": tree_hash,
            "snapshotHash": snapshot_hash,
            "sf6BuildId": build,
            "createdAt": self.clock.timestamp(),
            "instrumentDefinition": list(self.INSTRUMENT_PREFIXES),
            "excludedMutableRoots": [
                "reframework/data/fgcnote/devtools/queue/",
                "reframework/data/fgcnote/devtools/data/scratch/",
                "reframework/data/fgcnote/devtools/data/runs/",
                "reframework/data/fgcnote/devtools/data/staging/",
                "reframework/data/fgcnote/devtools/session.json",
