    def _require_write(self, runtime_id: str, task_id: str) -> list[sqlite3.Row]:
        now = self.clock.timestamp()
        with self.store.transaction():
            self.store.expire_claims()
            rows = self.store.connection.execute(
                "SELECT * FROM claims WHERE task_id=? AND mode='write' AND expires_at>? "
                "AND resource IN (?,?)",
