            "SELECT state FROM runtimes WHERE id=?", (runtime_id,),
        ).fetchone()
        if runtime and runtime["state"] in {"orphaned", "failed", "switching", "restoring"}:
            # Queue automation deliberately stops at uncertain runtime state.  The
            # low-level commands remain available to an explicit recovery owner.
            return
        row = self.store.connection.execute(
            "SELECT id, task_id, state FROM live_tests WHERE runtime_id=? "
            "AND state IN ('queued','preparing','needs_operator','testing','finishing') "
            "ORDER BY queue_order LIMIT 1", (runtime_id,),
        ).fetchone()
