        self._require_queue_route(args, self._runtime_id(args))
        timeout = args.timeout_seconds
        if timeout is None:
            return self._acquire_once(args)
        if timeout < 0:
            raise CommandError("-TimeoutSeconds cannot be negative.")
        deadline = time.monotonic() + timeout
        while True:
            try:
                return self._acquire_once(args)
            except CommandError as exc:
                if "conflicts with active claim" not in str(exc):
                    raise
                if time.monotonic() >= deadline:
                    raise NotReadyError(str(exc)) from exc
                time.sleep(min(0.1, max(0.01, deadline - time.monotonic())))

