            raise CommandError("Pass -Session, or run from a client with a detectable session ID.")
        session_client = args.session_client
        if not session_client:
            session_client = ("codex" if os.environ.get("CODEX_THREAD_ID") == session_id
                              else "claude-code" if session_id in {
                                  os.environ.get("CLAUDE_CODE_SESSION_ID"),
                                  os.environ.get("CLAUDE_SESSION_ID"),
                              } else "external")
        label = args.session_label
        with self.store.transaction():
            self.store.connection.execute(
                "UPDATE tasks SET session_client=?,session_id=?,"
                "session_label=COALESCE(?,session_label),updated_at=? WHERE id=?",
                (session_client, session_id, label, self.clock.timestamp(), task_id),
            )
            self.store.add_event(task_id, "task.session.updated", {
                "sessionClient": session_client, "sessionId": session_id,
                "sessionLabel": label,
            })
        return self.store.row_task(self.store.task(task_id))

    def dashboard(self, _args) -> dict:
        """Return one mutation-free snapshot for local monitoring clients."""
        now = self.clock.timestamp()
        tasks = []
        rows = self.store.connection.execute(
            "SELECT * FROM tasks ORDER BY updated_at DESC, id"
        ).fetchall()
        for row in rows:
            task = self.store.row_task(row)
            task["readiness"] = self.readiness(row["id"])
            task["claims"] = [
                {**self.store.row_claim(claim), "expired": claim["expires_at"] <= now}
                for claim in self.store.connection.execute(
                    "SELECT * FROM claims WHERE task_id=? ORDER BY resource", (row["id"],)
                ).fetchall()
            ]
            task["dependencies"] = [
                {"task": dependency["task_id"],
                 "prerequisite": dependency["prerequisite_task_id"],
                 "milestone": dependency["milestone"],
                 "createdAt": dependency["created_at"]}
                for dependency in self.store.connection.execute(
                    "SELECT * FROM dependencies WHERE task_id=? "
                    "ORDER BY prerequisite_task_id,milestone", (row["id"],)
                ).fetchall()
            ]
            tasks.append(task)

        runtime = self.store.connection.execute(
            "SELECT * FROM runtimes WHERE id='sf6'"
        ).fetchone()
        runtime_value = None
        if runtime:
            runtime_value = {
                "runtime": "sf6", "state": runtime["state"],
                "ownerTask": runtime["owner_task_id"],
                "resetOrRestartRequired": (
                    runtime["state"] if runtime["state"] in {
                        "reset_required", "restart_required"
                    } else None
                ),
                "failureReason": runtime["failure_reason"],
                "recoveryReason": runtime["recovery_reason"],
                "updatedAt": runtime["updated_at"],
            }
        current = self.store.connection.execute(
            "SELECT * FROM live_tests WHERE runtime_id='sf6' "
            "AND state IN ('preparing','needs_operator','testing','finishing') "
            "ORDER BY queue_order LIMIT 1"
        ).fetchone()
        queued = self.store.connection.execute(
            "SELECT * FROM live_tests WHERE runtime_id='sf6' AND state='queued' "
            "ORDER BY queue_order"
        ).fetchall()
        events = self.store.connection.execute(
            "SELECT * FROM events ORDER BY sequence DESC LIMIT 60"
        ).fetchall()
        return {
            "generatedAt": now,
            "lastSequence": events[0]["sequence"] if events else 0,
            "tasks": tasks,
            "runtime": runtime_value,
            "liveTests": {
                "current": self.store.row_live_test(current) if current else None,
                "queue": [self.store.row_live_test(item) for item in queued],
            },
            "events": [{
                "sequence": item["sequence"], "at": item["at"],
                "task": item["task_id"], "type": item["type"],
                "payload": json.loads(item["payload_json"]),
            } for item in events],
        }

    def show(self, args) -> dict:
        task_id = self.assert_task_id(args.task)
        task = self.store.task(task_id)
        claims = [self.store.row_claim(row) for row in self.store.connection.execute(
            "SELECT * FROM claims WHERE task_id=? ORDER BY resource", (task_id,)).fetchall()]
        dependencies = [
            {"task": row["task_id"], "prerequisite": row["prerequisite_task_id"],
             "milestone": row["milestone"], "createdAt": row["created_at"]}
            for row in self.store.connection.execute(
                "SELECT * FROM dependencies WHERE task_id=? ORDER BY prerequisite_task_id, milestone",
                (task_id,),).fetchall()
        ]
        milestones = [
            {"task": row["task_id"], "name": row["name"], "revision": row["revision"], "at": row["at"]}
            for row in self.store.connection.execute(
                "SELECT * FROM milestones WHERE task_id=? ORDER BY at, name", (task_id,)).fetchall()
        ]
        return {"task": self.store.row_task(task), "readiness": self.readiness(task_id),
                "claims": claims, "dependencies": dependencies, "milestones": milestones}

    def claim(self, args) -> dict:
        task_id = self.assert_task_id(args.task)
        if not args.resource:
            raise CommandError("Pass -Resource to claim.")
        if args.lease_seconds < 30:
            raise CommandError("-LeaseSeconds must be at least 30.")
        with self.store.transaction():
            task = self.store.task(task_id)
            if task["status"] not in {"running", "preparing"}:
                raise CommandError(
                    f"Task '{task_id}' cannot claim resources while status is '{task['status']}'."
                )
            self.store.expire_claims()
            conflicts = self.store.connection.execute(
                "SELECT task_id, mode FROM claims WHERE resource=? AND task_id<>? "
                "AND (?='write' OR mode='write') ORDER BY task_id",
                (args.resource, task_id, args.mode),
            ).fetchall()
            if conflicts:
                owners = ", ".join(f"{row['task_id']}[{row['mode']}]" for row in conflicts)
                raise CommandError(
                    f"Resource '{args.resource}' conflicts with active claim(s): {owners}"
                )
            existing = self.store.connection.execute(
                "SELECT * FROM claims WHERE task_id=? AND resource=?", (task_id, args.resource),
            ).fetchone()
            expires = (self.clock.now() + dt.timedelta(seconds=args.lease_seconds)).isoformat(
                timespec="microseconds").replace("+00:00", "Z")
            if existing:
                acquired = existing["acquired_at"]
                self.store.connection.execute(
                    "UPDATE claims SET mode=?, expires_at=? WHERE task_id=? AND resource=?",
                    (args.mode, expires, task_id, args.resource),
                )
            else:
                acquired = self.clock.timestamp()
                self.store.connection.execute(
                    "INSERT INTO claims VALUES(?,?,?,?,?)",
                    (task_id, args.resource, args.mode, acquired, expires),
                )
            self.store.add_event(task_id, "claim.acquired",
                                 {"resource": args.resource, "mode": args.mode, "expiresAt": expires})
            return {"task": task_id, "resource": args.resource, "mode": args.mode,
                    "acquiredAt": acquired, "expiresAt": expires}

    def release(self, args) -> dict:
        task_id = self.assert_task_id(args.task)
        if not args.resource:
            raise CommandError("Pass -Resource to release.")
        with self.store.transaction():
            self.store.task(task_id)
            cursor = self.store.connection.execute(
                "DELETE FROM claims WHERE task_id=? AND resource=?", (task_id, args.resource),
            )
            if cursor.rowcount == 0:
                raise CommandError(f"Task '{task_id}' does not hold '{args.resource}'.")
            return self.store.add_event(task_id, "claim.released", {"resource": args.resource})

    def depend(self, args) -> dict:
        task_id = self.assert_task_id(args.task)
        prerequisite = self.assert_task_id(args.on)
        if not args.name:
            raise CommandError("Pass the prerequisite milestone as -Name.")
        if task_id == prerequisite:
            raise CommandError("A task cannot depend on itself.")
        with self.store.transaction():
            self.store.task(task_id)
            self.store.task(prerequisite)
            existing = self.store.connection.execute(
                "SELECT * FROM dependencies WHERE task_id=? AND prerequisite_task_id=? AND milestone=?",
                (task_id, prerequisite, args.name),
            ).fetchone()
            if existing:
                return {"task": existing["task_id"], "prerequisite": existing["prerequisite_task_id"],
                        "milestone": existing["milestone"], "createdAt": existing["created_at"]}
            created = self.clock.timestamp()
            self.store.connection.execute(
                "INSERT INTO dependencies VALUES(?,?,?,?)", (task_id, prerequisite, args.name, created),
            )
            value = {"task": task_id, "prerequisite": prerequisite,
                     "milestone": args.name, "createdAt": created}
            self.store.add_event(task_id, "dependency.added", value)
            return value

    def milestone(self, args) -> dict:
        task_id = self.assert_task_id(args.task)
        if not args.name:
            raise CommandError("Pass -Name for the milestone.")
        if args.name in {"ready_for_integration", "merged"}:
            action = "complete" if args.name == "ready_for_integration" else "merged"
            raise CommandError(f"'{args.name}' is a system milestone. Use the '{action}' workflow action.")
        with self.store.transaction():
            task = self.store.task(task_id)
            existing = self.store.connection.execute(
                "SELECT * FROM milestones WHERE task_id=? AND name=?", (task_id, args.name),
            ).fetchone()
            if existing:
                if args.revision and existing["revision"] and existing["revision"] != args.revision:
                    raise CommandError(
                        f"Milestone '{task_id}:{args.name}' already points at revision '{existing['revision']}'."
                    )
                return {"task": task_id, "name": args.name, "revision": existing["revision"], "at": existing["at"]}
            value = {"task": task_id, "name": args.name,
                     "revision": args.revision or task["head_revision"], "at": self.clock.timestamp()}
            self.store.connection.execute(
                "INSERT INTO milestones VALUES(?,?,?,?)",
                (task_id, args.name, value["revision"], value["at"]),
            )
            self.store.connection.execute(
                "UPDATE tasks SET updated_at=? WHERE id=?", (self.clock.timestamp(), task_id),
            )
            self.store.add_event(task_id, "milestone.completed", value)
            return value

    def heartbeat(self, args) -> dict:
        task_id = self.assert_task_id(args.task)
        if args.lease_seconds < 30:
            raise CommandError("-LeaseSeconds must be at least 30.")
        with self.store.transaction():
            task = self.store.task(task_id)
            if task["status"] not in {"running", "preparing", "ready_for_integration"}:
                raise CommandError(f"Task '{task_id}' cannot heartbeat while status is '{task['status']}'.")
            self.store.expire_claims()
            now = self.clock.timestamp()
            expires = (self.clock.now() + dt.timedelta(seconds=args.lease_seconds)).isoformat(
                timespec="microseconds").replace("+00:00", "Z")
            self.store.connection.execute(
                "UPDATE tasks SET heartbeat_at=?, updated_at=? WHERE id=?", (now, now, task_id),
            )
            self.store.connection.execute(
                "UPDATE claims SET expires_at=? WHERE task_id=?", (expires, task_id),
            )
            self.store.connection.execute(
                "UPDATE runtimes SET lease_expires_at=?, updated_at=? WHERE owner_task_id=?",
                (expires, now, task_id),
            )
            return {"task": task_id, "heartbeatAt": now, "claimsExpireAt": expires}

    def complete(self, args) -> dict:
        task_id = self.assert_task_id(args.task)
        self.assert_runtime_clear(task_id)
        task = self.store.task(task_id)
        if task["status"] != "running":
            raise CommandError(f"Task '{task_id}' cannot complete from '{task['status']}'.")
        revision = args.revision
        if task["worktree"] and Path(task["worktree"]).exists():
            revision = self.git.run(Path(task["worktree"]), "rev-parse", "HEAD")[0]
        with self.store.transaction():
            task = self.store.task(task_id)
            if task["status"] != "running":
                raise CommandError(f"Task '{task_id}' cannot complete from '{task['status']}'.")
            now = self.clock.timestamp()
            self.store.connection.execute(
                "UPDATE tasks SET status='ready_for_integration', head_revision=?, summary=?, updated_at=? WHERE id=?",
                (revision, args.summary, now, task_id),
            )
            self.store.connection.execute(
                "INSERT INTO milestones VALUES(?,?,?,?)",
                (task_id, "ready_for_integration", revision, now),
            )
            self.store.add_event(task_id, "task.ready_for_integration",
                                 {"revision": revision, "summary": args.summary})
        return self.store.row_task(self.store.task(task_id))

    def merged(self, args) -> dict:
        task_id = self.assert_task_id(args.task)
        self.assert_runtime_clear(task_id)
        task = self.store.task(task_id)
        revision = args.revision or task["head_revision"]
        if not revision:
            raise CommandError("Pass -Revision with the integration commit.")
        repo = self.repo_path(task["repo"])
        integration_base = REPOS[task["repo"]][1]
        try:
            resolved = self.git.run(repo, "rev-parse", "--verify", f"{revision}^{{commit}}")[0]
            self.git.run(repo, "merge-base", "--is-ancestor", resolved, integration_base)
        except CommandError as exc:
            raise CommandError(
                f"Merged revision '{revision}' must be a commit reachable from "
                f"{task['repo']}:{integration_base}"
            ) from exc
        if task["status"] == "merged":
            try:
                self.git.run(repo, "rev-parse", "--verify", f"{task['head_revision']}^{{commit}}")
            except CommandError:
                # Canonical repair for a historical writer that accepted an
                # unresolvable integration revision.  A valid stored revision
                # remains immutable.
                with self.store.transaction():
                    now = self.clock.timestamp()
                    self.store.connection.execute(
                        "UPDATE tasks SET head_revision=?, updated_at=? WHERE id=?",
                        (resolved, now, task_id),
                    )
                    self.store.connection.execute(
                        "UPDATE milestones SET revision=?, at=? WHERE task_id=? AND name='merged'",
                        (resolved, now, task_id),
                    )
                    self.store.add_event(task_id, "task.merged_revision_repaired", {
                        "previousRevision": task["head_revision"], "revision": resolved,
                    })
                return self.store.row_task(self.store.task(task_id))
            raise CommandError(
                f"Task '{task_id}' is already merged at valid revision '{task['head_revision']}'."
            )
        with self.store.transaction():
            task = self.store.task(task_id)
            if task["status"] != "ready_for_integration":
                raise CommandError(f"Task '{task_id}' cannot be marked merged from '{task['status']}'.")
            summary = args.summary or task["summary"]
            now = self.clock.timestamp()
            self.store.connection.execute(
                "UPDATE tasks SET status='merged', head_revision=?, summary=?, updated_at=? WHERE id=?",
                (resolved, summary, now, task_id),
            )
            self.store.connection.execute("DELETE FROM claims WHERE task_id=?", (task_id,))
            self.store.connection.execute(
                "INSERT OR IGNORE INTO milestones VALUES(?,?,?,?)",
                (task_id, "merged", resolved, now),
            )
            self.store.add_event(task_id, "task.merged", {"revision": resolved, "summary": summary})
        return self.store.row_task(self.store.task(task_id))

    def fail(self, args) -> dict:
        task_id = self.assert_task_id(args.task)
        if not args.summary:
            raise CommandError("Pass the failure reason as -Summary.")
        with self.store.transaction():
            task = self.store.task(task_id)
            if task["status"] in {"merged", "failed"}:
                raise CommandError(f"Task '{task_id}' is already '{task['status']}'.")
            now = self.clock.timestamp()
            self.store.connection.execute(
                "UPDATE tasks SET status='failed', summary=?, updated_at=? WHERE id=?",
                (args.summary, now, task_id),
            )
            self.store.connection.execute("DELETE FROM claims WHERE task_id=?", (task_id,))
            self.store.add_event(task_id, "task.failed", {"reason": args.summary})
        return self.store.row_task(self.store.task(task_id))

    def events(self, args) -> list[dict]:
        rows = self.store.connection.execute(
            "SELECT * FROM events WHERE sequence>? ORDER BY sequence", (args.since,),
        ).fetchall()
        return [{"sequence": row["sequence"], "at": row["at"], "task": row["task_id"],
                 "type": row["type"], "payload": json.loads(row["payload_json"])} for row in rows]


