def run(arguments: list[str] | None = None, *, clock: Clock | None = None,
        git: GitAdapter | None = None) -> int:
    args = parser().parse_args(arguments)
    if args.action == "runtime-process-show":
        print_json(sf6_process_snapshot())
        return 0
    root = Path(args.root).resolve() if args.root else Path(__file__).resolve().parents[1]
    runtime = Path(args.runtime_path).resolve() if args.runtime_path else root / ".agent-runtime"
    clock = clock or Clock()
    registry = Registry(runtime, clock)
    service = CoordinationService(root, registry, clock, git or GitAdapter())
    try:
        runtime_actions = {
            "runtime-bootstrap": "bootstrap", "runtime-init": "init",
            "runtime-show": "show", "runtime-acquire": "acquire",
            "runtime-deploy": "deploy", "runtime-activate": "activate",
            "runtime-release": "release", "runtime-recover": "recover",
        }
        if args.action in runtime_actions:
            runtime = RuntimeCoordinator(service)
            print_json(getattr(runtime, runtime_actions[args.action])(args))
            return 0
        live_test_actions = {
            "runtime-test-request": "request", "runtime-test-show": "show",
            "runtime-test-wait": "wait", "runtime-test-watch": "watch",
            "runtime-test-checkpoint": "checkpoint", "runtime-test-confirm": "confirm",
            "runtime-test-finish": "finish", "runtime-test-cancel": "cancel",
        }
        if args.action in live_test_actions:
            runtime_coordinator = RuntimeCoordinator(service)
            queue = LiveTestQueue(service, runtime_coordinator)
            print_json(getattr(queue, live_test_actions[args.action])(args))
            return 0
        if args.action == "ready":
            result = service.readiness(service.assert_task_id(args.task))
            print_json(result)
            return 0 if result["ready"] else EXIT_NOT_READY
        if args.action == "wait":
            timeout_seconds = 3600 if args.timeout_seconds is None else args.timeout_seconds
            if timeout_seconds < 1:
                raise CommandError("-TimeoutSeconds must be at least 1.")
            if args.poll_milliseconds < 50:
                raise CommandError("-PollMilliseconds must be at least 50.")
            deadline = time.monotonic() + timeout_seconds
            while True:
                result = service.readiness(service.assert_task_id(args.task))
                if result["failed"]:
                    print_json(result)
                    return EXIT_PREREQUISITE_FAILED
                if result["ready"]:
                    print_json(result)
                    return 0
                if time.monotonic() >= deadline:
                    print_json(result)
                    return EXIT_NOT_READY
                time.sleep(args.poll_milliseconds / 1000)
        method = getattr(service, args.action)
        print_json(method(args))
        return 0
    finally:
        registry.close()


def main() -> int:
    try:
        return run()
    except NotReadyError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return EXIT_NOT_READY
    except (CommandError, sqlite3.Error, OSError, ValueError) as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return EXIT_ERROR


if __name__ == "__main__":
    raise SystemExit(main())

