function Find-CompatiblePython {
    $candidates = if ($env:AGENTCTL_PYTHON) {
        @($env:AGENTCTL_PYTHON)
    } elseif ($IsWindows) {
        @('python', 'py', 'python3')
    } else {
        @('python3', 'python')
    }

    foreach ($candidate in $candidates) {
        $commands = @(Get-Command $candidate -CommandType Application -All -ErrorAction SilentlyContinue)
        if (-not $env:AGENTCTL_PYTHON) {
            $commands = @($commands | Where-Object {
                $_.Source -notlike '*\Microsoft\WindowsApps\*' -and
                $_.Source -notlike '*\mise\shims\*' -and
                $_.Source -notlike '*/mise/shims/*'
            })
        }
        $command = $commands[0]
        if (-not $command) {
            continue
        }

        $prefix = if ($candidate -eq 'py') { @('-3') } else { @() }
        $probeArguments = @($prefix) + @('-c', 'import sys; raise SystemExit(0 if sys.version_info >= (3, 10) else 1)')
        & $command.Source @probeArguments *> $null
        if ($LASTEXITCODE -eq 0) {
            return @{ Path = $command.Source; Prefix = $prefix }
        }
    }

    return $null
}

$python = Find-CompatiblePython
if (-not $python) {
    $overrideHint = if ($env:AGENTCTL_PYTHON) {
        " AGENTCTL_PYTHON='$($env:AGENTCTL_PYTHON)' is not a compatible executable."
    } else {
        ' Set AGENTCTL_PYTHON to an explicit interpreter path if Python is not on PATH.'
    }
    Write-Error "Python 3.10 or newer is required for the canonical SQLite agent coordination CLI.$overrideHint"
    exit 1
}

$hadPythonUtf8 = Test-Path Env:PYTHONUTF8
$previousPythonUtf8 = $env:PYTHONUTF8
try {
    $env:PYTHONUTF8 = '1'
    $pythonArguments = @($python.Prefix) + @($tool) + @($args)
    & $python.Path @pythonArguments
    $exitCode = $LASTEXITCODE
} finally {
    if ($hadPythonUtf8) {
        $env:PYTHONUTF8 = $previousPythonUtf8
    } else {
        Remove-Item Env:PYTHONUTF8 -ErrorAction SilentlyContinue
    }
}

exit $exitCode

#!/usr/bin/env python3
"""Serve the read-only agent coordination dashboard on localhost."""
from __future__ import annotations

import argparse
import errno
from http import HTTPStatus
from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer
import json
from pathlib import Path
import subprocess
import sys
from urllib.error import HTTPError, URLError
from urllib.request import urlopen


TOOLS = Path(__file__).resolve().parent
STATIC = TOOLS / "agent-dashboard"
AGENTCTL = TOOLS / "agentctl.py"


def dashboard_url(host: str, port: int) -> str:
    display_host = f"[{host}]" if ":" in host and not host.startswith("[") else host
    return f"http://{display_host}:{port}"


def is_agent_desk_running(url: str) -> bool:
    try:
        with urlopen(f"{url}/api/snapshot", timeout=1.5) as response:
            value = json.load(response)
    except (HTTPError, URLError, OSError, TimeoutError, json.JSONDecodeError):
        return False
    return (isinstance(value, dict) and isinstance(value.get("tasks"), list)
            and isinstance(value.get("liveTests"), dict)
            and "generatedAt" in value)


def snapshot(root: Path, runtime_path: Path | None = None) -> bytes:
    command = [sys.executable, str(AGENTCTL), "dashboard", "-Root", str(root)]
    if runtime_path:
        command.extend(["-RuntimePath", str(runtime_path)])
    result = subprocess.run(command, capture_output=True, text=True, timeout=20)
    if result.returncode:
        raise RuntimeError(result.stderr.strip() or "agentctl dashboard failed")
    return result.stdout.encode("utf-8")


def handler(root: Path, runtime_path: Path | None):
    class DashboardHandler(SimpleHTTPRequestHandler):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, directory=str(STATIC), **kwargs)

        def do_GET(self):  # noqa: N802 - stdlib handler API
            if self.path.split("?", 1)[0] != "/api/snapshot":
                return super().do_GET()
            try:
                body = snapshot(root, runtime_path)
                status = HTTPStatus.OK
            except (OSError, subprocess.SubprocessError, RuntimeError) as exc:
                body = json.dumps({"error": str(exc)}, ensure_ascii=False).encode("utf-8")
                status = HTTPStatus.SERVICE_UNAVAILABLE
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, format, *args):  # noqa: A002 - stdlib signature
            if self.path.split("?", 1)[0] != "/api/snapshot":
                super().log_message(format, *args)

    return DashboardHandler


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, default=8765)
    parser.add_argument("--root", type=Path, default=TOOLS.parent)
    parser.add_argument("--runtime-path", type=Path)
    args = parser.parse_args()
    if args.host not in {"127.0.0.1", "localhost", "::1"}:
        parser.error("The dashboard is local-only; use 127.0.0.1, localhost, or ::1")
