    @staticmethod
    def _resolved_link(path: Path) -> tuple[str, Path]:
        if not path.is_symlink():
            if path.exists():
                raise CommandError(f"Refusing to replace physical path: {path}")
            raise CommandError(f"Required symlink is missing: {path}")
        raw = os.readlink(path)
        target = Path(raw)
        if not target.is_absolute():
            target = path.parent / target
        target = Path(os.path.abspath(target))
        if not target.exists():
            raise CommandError(f"Refusing broken symlink {path} -> {raw}")
        return raw, target

