def assert_runtime_clear(self, task_id: str) -> None:
    live_tests = self.store.connection.execute(
        "SELECT id, state FROM live_tests WHERE task_id=? "
        "AND state IN ('queued','preparing','needs_operator','testing','finishing') "
        "ORDER BY queue_order", (task_id,),
    ).fetchall()
    if live_tests:
        detail = ", ".join(f"{row['id']}[{row['state']}]" for row in live_tests)
        raise CommandError(f"Task '{task_id}' still has live test work: {detail}")
    write_claims = self.store.connection.execute(
        "SELECT resource FROM claims WHERE task_id=? AND mode='write' AND resource LIKE 'runtime:%'",
        (task_id,),
    ).fetchall()
    if write_claims:
        resources = ", ".join(row["resource"] for row in write_claims)
        raise CommandError(f"Task '{task_id}' still holds runtime write claim(s): {resources}")
    rows = self.store.connection.execute(
        "SELECT r.id, r.state, r.active_deployment_id FROM runtimes r "
        "LEFT JOIN deployments d ON d.id=r.active_deployment_id "
        "WHERE (r.owner_task_id=? OR r.release_pending_task_id=? OR d.owner_task_id=?) "
        "AND r.state NOT IN ('unmanaged','released')",
        (task_id, task_id, task_id),
    ).fetchall()
    unresolved = [row for row in rows if not self.is_warm_runtime(row["id"], task_id)]
    if unresolved:
        detail = ", ".join(f"{row['id']}[{row['state']}]" for row in unresolved)
        raise CommandError(
            f"Task '{task_id}' still owns active/unresolved live runtime state: {detail}"
        )

def is_warm_runtime(self, runtime_id: str, task_id: str | None = None) -> bool:
    """Return whether a tested deployment is parked without queue ownership."""
    runtime = self.store.connection.execute(
        "SELECT * FROM runtimes WHERE id=?", (runtime_id,),
    ).fetchone()
    if not runtime or runtime["state"] != "active" or not runtime["active_deployment_id"]:
        return False
    if task_id is not None and runtime["owner_task_id"] != task_id:
        return False
    open_test = self.store.connection.execute(
        "SELECT 1 FROM live_tests WHERE runtime_id=? "
        "AND state IN ('preparing','needs_operator','testing','finishing') LIMIT 1",
        (runtime_id,),
    ).fetchone()
    if open_test:
        return False
    claim = self.store.connection.execute(
        "SELECT 1 FROM claims WHERE resource IN (?,?) LIMIT 1",
        (f"runtime:{runtime_id}/deployment", f"runtime:{runtime_id}/session"),
    ).fetchone()
    if claim:
        return False
    tested = self.store.connection.execute(
        "SELECT 1 FROM live_tests WHERE runtime_id=? AND deployment_id=? "
        "AND task_id=? AND state IN ('passed','failed','inconclusive','cancelled') LIMIT 1",
        (runtime_id, runtime["active_deployment_id"], runtime["owner_task_id"]),
    ).fetchone()
    return bool(tested)

