def expire_claims(self) -> None:
    now = self.clock.timestamp()
    rows = self.connection.execute(
        "SELECT * FROM claims WHERE expires_at <= ? ORDER BY task_id, resource", (now,),
    ).fetchall()
    for row in rows:
        match = re.fullmatch(r"runtime:([^/]+)/(deployment|session)", row["resource"])
        if match and row["mode"] == "write":
            runtime = self.connection.execute(
                "SELECT * FROM runtimes WHERE id=?", (match.group(1),),
            ).fetchone()
            if (runtime and runtime["owner_task_id"] == row["task_id"]
                    and runtime["state"] not in {"unmanaged", "released"}):
                reason = (f"write lease expired for {row['task_id']} while runtime was "
                          f"{runtime['state']}; reconcile before any filesystem switch")
                self.connection.execute(
                    "UPDATE runtimes SET state='orphaned', failure_reason=?, updated_at=? WHERE id=?",
                    (reason, now, runtime["id"]),
                )
                if runtime["active_deployment_id"]:
                    self.connection.execute(
                        "UPDATE deployments SET state='orphaned', failure_reason=? WHERE id=? "
                        "AND state NOT IN ('released','failed')",
                        (reason, runtime["active_deployment_id"]),
                    )
                self.add_event(row["task_id"], "runtime.orphaned", {
                    "runtime": runtime["id"], "reason": reason,
                    "expiredResource": row["resource"],
                })
        self.connection.execute(
            "DELETE FROM claims WHERE task_id = ? AND resource = ?",
            (row["task_id"], row["resource"]),
        )
        self.add_event(row["task_id"], "claim.expired",
                       {"resource": row["resource"], "mode": row["mode"]})

