const $ = (selector) => document.querySelector(selector);
const state = { snapshot: null, sound: localStorage.getItem("agentDeskSound") === "on", firstLoad: true };
const terminal = new Set(["merged", "failed"]);
const escapeHtml = (value = "") => String(value).replace(/[&<>'"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));
const shortId = (value) => value ? (value.length > 18 ? `${value.slice(0, 8)}…${value.slice(-6)}` : value) : "未記錄";
const localTime = (value) => value ? new Date(value).toLocaleString("zh-TW", {hour12:false}) : "—";

function badge(value) { return `<span class="badge ${escapeHtml(value)}">${escapeHtml(value)}</span>`; }
function sessionMarkup(task) {
  const recorded = Boolean(task.sessionId);
  return `<div class="session">
    <div class="session-label">${escapeHtml(task.sessionLabel || (recorded ? task.title : "舊資料 · Session 未記錄"))}</div>
    <div class="session-meta">${escapeHtml(task.sessionClient || task.owner)} · ${escapeHtml(shortId(task.sessionId))}</div>
  </div>`;
}
function taskMarkup(task) {
  const claims = task.claims.length ? task.claims.map(c => `<span class="chip ${c.mode} ${c.expired ? "expired" : ""}">${escapeHtml(c.mode)} · ${escapeHtml(c.resource)}</span>`).join("") : '<span class="muted">沒有 claims</span>';
  const blockers = [...task.readiness.blockers, ...task.readiness.failed];
  const deps = blockers.length ? blockers.map(d => `<span class="chip">等待 ${escapeHtml(d.task)}:${escapeHtml(d.milestone)}</span>`).join("") : '<span class="muted">沒有未完成的 dependency</span>';
  return `<details class="task ${task.status === "failed" ? "alert" : ""}">
    <summary><div class="task-top"><div><h3>${escapeHtml(task.title)}</h3><div class="task-id">${escapeHtml(task.id)}</div></div>${badge(task.status)}</div>${sessionMarkup(task)}</summary>
    <div class="task-body"><dl class="detail">
      <dt>Repo</dt><dd>${escapeHtml(task.repo)}</dd><dt>Owner</dt><dd>${escapeHtml(task.owner)}</dd>
      <dt>Branch</dt><dd>${escapeHtml(task.branch)}</dd><dt>Worktree</dt><dd>${escapeHtml(task.worktree || "—")}</dd>
      <dt>Heartbeat</dt><dd>${localTime(task.heartbeatAt)}</dd>
    </dl><p class="eyebrow">CLAIMS</p><div class="chips">${claims}</div>
    <p class="eyebrow" style="margin-top:14px">DEPENDENCIES</p><div class="chips">${deps}</div></div>
  </details>`;
}
function testRow(test, index, current = false) {
  return `<div class="queue-row"><div class="queue-number">${current ? "NOW" : index}</div><div><strong>${escapeHtml(test.purpose)}</strong><div class="muted">${escapeHtml(test.task)} · ${escapeHtml(test.operatorInstructions)}</div></div>${badge(test.state)}</div>`;
}
function render(data) {
  const visible = data.tasks.filter(t => !terminal.has(t.status));
  const waiting = visible.filter(t => !t.readiness.ready).length;
  const activeClaims = visible.flatMap(t => t.claims).filter(c => !c.expired).length;
  $("#summary").innerHTML = [
    [visible.length,"進行中任務"], [waiting,"等待前置"], [activeClaims,"有效 Claims"],
    [(data.liveTests.current ? 1 : 0) + data.liveTests.queue.length,"SF6 測試需求"]
  ].map(([n,l]) => `<div class="metric"><strong>${n}</strong><span>${l}</span></div>`).join("");

  const runtime = data.runtime;
  const queue = data.liveTests;
  $("#runtime").innerHTML = `<div class="runtime-layout"><div class="runtime-card">
    <p class="eyebrow">RUNTIME STATE</p><div class="runtime-state ${escapeHtml(runtime?.state || "")}">${escapeHtml(runtime?.state || "尚未初始化")}</div>
    <div class="muted">Owner: ${escapeHtml(runtime?.ownerTask || "目前無人使用")}</div>
    ${runtime?.failureReason ? `<p class="failed">${escapeHtml(runtime.failureReason)}</p>` : ""}</div>
    <div class="queue-card"><p class="eyebrow">LIVE TEST FIFO</p>
      ${queue.current ? testRow(queue.current, 0, true) : '<div class="muted">目前沒有進行中的 live test</div>'}
      ${queue.queue.map((t,i) => testRow(t,i+1)).join("")}
    </div></div>`;

  const includeHistory = $("#history").checked;
  const tasks = data.tasks.filter(t => includeHistory || !terminal.has(t.status));
  $("#tasks").innerHTML = tasks.length ? tasks.map(taskMarkup).join("") : '<div class="empty">目前沒有符合條件的任務</div>';
  $("#events").innerHTML = data.events.slice(0, 18).map(e => `<div class="event"><time>${new Date(e.at).toLocaleTimeString("zh-TW", {hour12:false})}</time><span class="event-task">${escapeHtml(e.task || "system")}</span><span class="event-type">${escapeHtml(e.type)}</span></div>`).join("") || '<div class="empty">還沒有事件</div>';
  $("#updated").textContent = `更新 ${localTime(data.generatedAt)}`;
}

function notifyChanges(next) {
  if (!state.snapshot || state.firstLoad) return;
  const previousTasks = new Map(state.snapshot.tasks.map(t => [t.id, t.status]));
  const messages = [];
  for (const task of next.tasks) {
    if (previousTasks.has(task.id) && previousTasks.get(task.id) !== task.status && ["ready_for_integration","failed"].includes(task.status)) messages.push(`${task.sessionLabel || task.title} → ${task.status}`);
  }
  const oldCurrent = state.snapshot.liveTests.current;
  const current = next.liveTests.current;
  if (current?.state === "needs_operator" && `${oldCurrent?.id}:${oldCurrent?.state}` !== `${current.id}:${current.state}`) messages.push(`SF6 等待操作：${current.operatorPrompt || current.operatorInstructions}`);
  if (["failed","orphaned","reset_required","restart_required"].includes(next.runtime?.state) && next.runtime?.state !== state.snapshot.runtime?.state) messages.push(`SF6 runtime：${next.runtime.state}`);
  if (messages.length) { if (state.sound) beep(); showToast(messages.join("\n")); }
}
function beep() {
  const AudioContext = window.AudioContext || window.webkitAudioContext;
  const ctx = new AudioContext(); const gain = ctx.createGain(); const osc = ctx.createOscillator();
  osc.frequency.setValueAtTime(660, ctx.currentTime); osc.frequency.setValueAtTime(880, ctx.currentTime + .12);
  gain.gain.setValueAtTime(.001, ctx.currentTime); gain.gain.exponentialRampToValueAtTime(.16, ctx.currentTime + .02); gain.gain.exponentialRampToValueAtTime(.001, ctx.currentTime + .32);
  osc.connect(gain).connect(ctx.destination); osc.start(); osc.stop(ctx.currentTime + .34);
}
function showToast(message) { const toast = $("#toast"); toast.textContent = message; toast.classList.add("show"); setTimeout(() => toast.classList.remove("show"), 5000); }
function updateSound() { $("#sound").textContent = state.sound ? "🔊 聲音開啟" : "🔇 聲音關閉"; $("#sound").setAttribute("aria-pressed", String(state.sound)); }
async function refresh() {
  try {
    const response = await fetch("/api/snapshot", {cache:"no-store"});
    if (!response.ok) throw new Error((await response.json()).error || response.statusText);
    const next = await response.json(); notifyChanges(next); state.snapshot = next; state.firstLoad = false; render(next);
    $("#connection").className = "connection online"; $("#connection").innerHTML = "<span></span>即時更新";
  } catch (error) {
    $("#connection").className = "connection offline"; $("#connection").innerHTML = "<span></span>連線中斷"; showToast(error.message);
  }
}
$("#sound").addEventListener("click", () => { state.sound = !state.sound; localStorage.setItem("agentDeskSound", state.sound ? "on" : "off"); updateSound(); if (state.sound) beep(); });
$("#history").addEventListener("change", () => state.snapshot && render(state.snapshot));
updateSound(); refresh(); setInterval(refresh, 2500);

